;; State Machine Integration Example
;; Generated by MSX Retro Game IDE
;;
;; Shows how to integrate the state machine system
;; with existing ECS and game systems
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

INCLUDE "state_machine_system.asm"
INCLUDE "ecs_main_loop.asm"

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Enhanced Game Initialization with State Machine
;; Input: None
;; Output: None
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
INIT_GAME_WITH_STATE_MACHINE:
    ; Initialize basic MSX setup
    DI
    LD SP, #F380
    
    ; Reset interrupt hooks
    LD A, #C9
    LD (HKEY), A
    LD (TIMI), A
    EI
    
    ; Initialize graphics mode
    LD A, 2
    CALL CHGMOD
    
    ; Initialize ECS system
    CALL ECS_INIT
    
    ; Initialize state machine (this replaces direct ECS main loop)
    CALL INIT_STATE_MACHINE
    
    ; Load initial menu data
    CALL LOAD_MENU_GRAPHICS
    
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Enhanced State Logic with ECS Integration
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Playing State with ECS Integration
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
logic_playing:
    ; Read input using MSX-specific routine
    CALL MSX_READ_JOYSTICK
    LD (input_state), A
    
    ; Update ECS systems only in playing state
    CALL UPDATE_ALL_SYSTEMS
    
    ; Check for pause (SELECT or specific key)
    LD A, (input_state)
    BIT 6, A                    ; Pause key
    JR Z, playing_no_pause
    
    ; Check for new press
    LD A, (prev_input_state)
    BIT 6, A
    JR NZ, playing_no_pause
    
    ; Pause the game
    LD A, STATE_PAUSED
    CALL CHANGE_GAME_STATE
    RET

playing_no_pause:
    ; Check for player death through ECS health component
    CALL CHECK_PLAYER_HEALTH_ECS
    CP 0
    JR NZ, playing_alive
    
    ; Player died
    LD A, STATE_DYING
    CALL CHANGE_GAME_STATE
    CALL TRIGGER_DEATH_EFFECTS
    RET

playing_alive:
    ; Check for level completion
    CALL CHECK_LEVEL_COMPLETE_ECS
    OR A
    JR Z, playing_continue
    
    ; Level complete - change zone
    LD A, STATE_CHANGING_ZONE
    CALL CHANGE_GAME_STATE
    CALL PREPARE_NEXT_ZONE
    
playing_continue:
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Menu State with Enhanced Graphics
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
logic_menu:
    ; Update menu animations (could use ECS for menu entities)
    CALL UPDATE_MENU_ANIMATIONS
    
    ; Read input
    CALL MSX_READ_JOYSTICK
    LD (input_state), A
    
    ; Handle menu navigation
    LD A, (input_state)
    LD B, A
    LD A, (prev_input_state)
    XOR B                       ; Get newly pressed buttons
    AND B                       ; Mask with current state
    LD C, A                     ; C = newly pressed buttons
    
    ; Check UP
    BIT 0, C
    JR Z, menu_no_up
    CALL MOVE_MENU_UP
    CALL PLAY_MENU_SOUND
    
menu_no_up:
    ; Check DOWN  
    BIT 1, C
    JR Z, menu_no_down
    CALL MOVE_MENU_DOWN
    CALL PLAY_MENU_SOUND
    
menu_no_down:
    ; Check FIRE (start game)
    BIT 4, C
    JR Z, menu_no_fire
    
    ; Get current menu selection
    LD A, (menu_selection)
    OR A
    JR Z, menu_start_game
    CP 1
    JR Z, menu_options
    CP 2
    JR Z, menu_exit
    
menu_start_game:
    LD A, STATE_LOADING
    CALL CHANGE_GAME_STATE
    CALL PLAY_SELECT_SOUND
    RET
    
menu_options:
    ; Handle options menu
    CALL SHOW_OPTIONS_SCREEN
    RET
    
menu_exit:
    ; Exit to MSX BASIC
    CALL RESTORE_STATE_MACHINE
    RST 0
    
menu_no_fire:
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Loading State with Progress Display
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
logic_loading:
    ; Calculate loading progress
    LD A, (state_timer)
    LD B, A
    
    ; Update progress bar
    CALL UPDATE_LOADING_BAR
    
    ; Perform loading tasks at specific intervals
    CP 30
    JR NZ, loading_check_60
    CALL LOAD_LEVEL_GRAPHICS
    JR loading_continue
    
loading_check_60:
    CP 60
    JR NZ, loading_check_90
    CALL INIT_LEVEL_ENTITIES
    JR loading_continue
    
loading_check_90:
    CP 90
    JR NZ, loading_check_120
    CALL SETUP_PLAYER_ENTITY
    JR loading_continue
    
loading_check_120:
    CP 120
    JR C, loading_continue
    
    ; Loading complete
    LD A, STATE_PLAYING
    CALL CHANGE_GAME_STATE
    CALL CLEAR_LOADING_SCREEN
    
loading_continue:
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Helper Functions for ECS Integration
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

CHECK_PLAYER_HEALTH_ECS:
    ; Find player entity (assuming ID 0 or specific component)
    LD A, 0                     ; Player entity ID
    LD B, COMP_ID_HEALTH        ; Health component
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JR Z, check_health_not_found
    
    ; Get health value (assuming first byte is current health)
    LD A, (HL)
    RET

check_health_not_found:
    LD A, 1                     ; Assume alive if no health component
    RET

CHECK_LEVEL_COMPLETE_ECS:
    ; Check level completion conditions
    ; This could check for specific entities, flags, etc.
    LD A, (level_complete_flag)
    RET

TRIGGER_DEATH_EFFECTS:
    ; Stop player movement
    ; Play death sound
    CALL PLAY_DEATH_SOUND
    RET

PREPARE_NEXT_ZONE:
    ; Set up next zone data
    LD A, (current_zone)
    INC A
    LD (next_zone), A
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Menu System Functions
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

UPDATE_MENU_ANIMATIONS:
    ; Animate menu background, logos, etc.
    ; Could use ECS entities for complex menu animations
    LD A, (state_timer)
    AND 15                      ; Simple blinking effect
    JR Z, menu_blink_on
    
    ; Turn off highlight
    CALL MENU_HIGHLIGHT_OFF
    RET
    
menu_blink_on:
    CALL MENU_HIGHLIGHT_ON
    RET

MOVE_MENU_UP:
    LD A, (menu_selection)
    OR A
    JR Z, menu_wrap_to_bottom
    DEC A
    LD (menu_selection), A
    CALL UPDATE_MENU_CURSOR
    RET
    
menu_wrap_to_bottom:
    LD A, (max_menu_items)
    DEC A
    LD (menu_selection), A
    CALL UPDATE_MENU_CURSOR
    RET

MOVE_MENU_DOWN:
    LD A, (menu_selection)
    LD B, A
    LD A, (max_menu_items)
    DEC A
    CP B
    JR Z, menu_wrap_to_top
    
    INC B
    LD A, B
    LD (menu_selection), A
    CALL UPDATE_MENU_CURSOR
    RET
    
menu_wrap_to_top:
    XOR A
    LD (menu_selection), A
    CALL UPDATE_MENU_CURSOR
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Enhanced Loading Functions
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

LOAD_LEVEL_GRAPHICS:
    ; Load tiles, sprites, colors for current level
    CALL LOAD_LEVEL_TILES
    CALL LOAD_LEVEL_SPRITES
    CALL LOAD_LEVEL_COLORS
    RET

INIT_LEVEL_ENTITIES:
    ; Clear existing entities
    CALL ECS_CLEANUP_ALL_ENTITIES
    
    ; Create level-specific entities
    LD A, (current_level)
    LD HL, level_entity_table
    CALL LOAD_ENTITIES_FROM_TABLE
    RET

SETUP_PLAYER_ENTITY:
    ; Create player entity with all components
    CALL ALLOCATE_ENTITY
    CP 0xFF
    RET Z                       ; Failed
    
    ; Store player entity ID
    LD (player_entity_id), A
    
    ; Add transform component
    LD B, COMP_ID_TRANSFORM
    CALL ADD_COMPONENT_TO_ENTITY
    
    ; Add physics component
    LD A, (player_entity_id)
    LD B, COMP_ID_PHYSICS
    CALL ADD_COMPONENT_TO_ENTITY
    
    ; Add renderer component
    LD A, (player_entity_id)
    LD B, COMP_ID_RENDERER
    CALL ADD_COMPONENT_TO_ENTITY
    
    ; Add health component
    LD A, (player_entity_id)
    LD B, COMP_ID_HEALTH
    CALL ADD_COMPONENT_TO_ENTITY
    
    ; Initialize player position and stats
    CALL INIT_PLAYER_STATS
    RET

UPDATE_LOADING_BAR:
    ; Display loading progress (0-120 -> 0-100%)
    ; B contains current timer value
    LD A, B
    CP 120
    JR C, loading_bar_calc
    LD A, 120
    
loading_bar_calc:
    ; Convert to percentage (A * 100 / 120)
    ; Simplified: A * 5 / 6 ≈ percentage
    LD L, A
    LD H, 0
    ADD HL, HL                  ; *2
    ADD HL, HL                  ; *4  
    LD A, L
    ADD A, L                    ; *5
    LD B, 6
    ; Simple division by 6 (not exact but close enough)
    SRL A
    SRL A                       ; Rough /4 approximation
    
    ; Display percentage in A
    CALL DISPLAY_LOADING_PERCENTAGE
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Audio Functions
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

PLAY_MENU_SOUND:
    ; Play menu navigation sound
    RET

PLAY_SELECT_SOUND:
    ; Play selection sound
    RET

PLAY_DEATH_SOUND:
    ; Play death sound effect
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Graphics Helper Functions
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

MENU_HIGHLIGHT_ON:
    ; Turn on menu item highlight
    RET

MENU_HIGHLIGHT_OFF:
    ; Turn off menu item highlight  
    RET

UPDATE_MENU_CURSOR:
    ; Update cursor position based on menu_selection
    RET

DISPLAY_LOADING_PERCENTAGE:
    ; Display loading percentage in A register
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
