;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

LOAD_MENU_GRAPHICS:
    RET

SHOW_OPTIONS_SCREEN:
    RET

CLEAR_LOADING_SCREEN:
    RET

LOAD_LEVEL_TILES:
    RET

LOAD_LEVEL_SPRITES:
    RET

