    RET

INIT_PLAYER_STATS:
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Data Section
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

menu_selection:
    DB 0                        ; Current menu item (0-based)

max_menu_items:
    DB 3                        ; Number of menu items

current_level:
    DB 1                        ; Current level number

current_zone:
    DB 0                        ; Current zone

next_zone:
    DB 0                        ; Next zone to load

level_complete_flag:
    DB 0                        ; Level completion flag

player_entity_id:
    DB 0xFF                     ; Player entity ID (0xFF = invalid)

; Level entity table would contain template data
level_entity_table:
    ; This would be populated with your level data
    DW 0000H                    ; Placeholder
